static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);System.out.println("PASS "+name);}
static void write(Path root,List<String> files,String name,String source)throws Exception{Path p=root.resolve(name);Files.createDirectories(p.getParent());Files.write(p,source.getBytes(StandardCharsets.UTF_8));files.add(p.toString());}
static String method(String source,String name){int start=source.indexOf(name),body=source.indexOf('{',start),depth=0;if(start<0)throw new AssertionError(name);for(int i=body;i<source.length();i++){if(source.charAt(i)=='{')depth++;if(source.charAt(i)=='}'&&--depth==0)return source.substring(start,i+1);}throw new AssertionError(name);}
static ExposureMatch.Sample sample(float target,long time,int iso){return new ExposureMatch.Sample(target,target,time,iso,33333333L,2f,2,1000);}
static float fix(ExposureMatch.Sample p,float target,Float reported,long ns,int iso,boolean manual,boolean flash){return ExposureMatch.compare(p,target,reported,ns,iso,2,manual,flash).amount;}
