ExposureMatch.Sample boosted=new ExposureMatch.Sample(1,1f,10000000L,200,33333333L,2f,2,1000,200);
check(ExposureMatch.compare(boosted,1,1f,20000000,200,2,false,false,100).amount==0,"Equal final exposure with different sensor ISO/time and post-RAW gain is not corrected twice");
check(ExposureMatch.compare(boosted,1,1f,10000000,200,2,true,false,100).amount==1,"A missing post-RAW boost in the still receives only its verified one-stop difference");
check(ExposureMatch.compare(boosted,1,1f,10000000,200,2,true,false,200).amount==0,"Copying the same sensor exposure and digital boost preserves JPEG brightness without correction");
