check(darkest.target==-2&&brightest.target==2&&darkest.fine==0&&brightest.fine==0,"New +/-3 endpoints preserve the previous native +/-2 effects without deepening the extremes");
check(Math.abs(ExposureScale.plan(-2,scaleLimits).target+4f/3)<.001&&ExposureScale.plan(-2,scaleLimits).target>-2,"New -2 is gentler than the former -2 because it maps to approximately -1.33 actual EV");
boolean steps=true;float previous=-10;for(int tick=0;tick<=60;tick++){float level=ExposureScale.value(tick,scaleLimits);ExposureScale.Plan plan=ExposureScale.plan(level,scaleLimits);steps&=ExposureScale.progress(level,scaleLimits)==tick&&plan.target>previous&&Math.abs(plan.hardware+plan.fine-plan.target)<.0001&&scaleLimits.ticks(plan.hardware)>=scaleLimits.low&&scaleLimits.ticks(plan.hardware)<=scaleLimits.high;previous=plan.target;}check(steps,"Every soft tick roundtrips, increases effective exposure, and splits only into legal hardware plus a small residual");
