Bitmap fineInput=Bitmap.createBitmap(2,2,Bitmap.Config.ARGB_8888);for(int y=0;y<2;y++)fineInput.setPixels(new int[]{0xff404040,0xff404040},0,2,0,y,2,1);boolean smallest=true;for(float amount:new float[]{0,.5f,1}){Film.Settings f=new Film.Settings();f.stock=0;f.grain=f.fade=0;f.strength=amount;f.exposure=0;Bitmap baseline=Film.develop(fineInput,f);int zero=pixel(baseline);f.exposure=ExposureMatch.withFine(neutralMatch,tiny).amount;Bitmap up=Film.develop(fineInput,f);f.exposure=ExposureMatch.withFine(neutralMatch,-tiny).amount;Bitmap down=Film.develop(fineInput,f);smallest&=pixel(up)>zero&&pixel(down)<zero;baseline.recycle();up.recycle();down.recycle();}check(smallest,"Actual developed pixels change for the minimum fine adjustment at zero, half and full film strength");fineInput.recycle();
boolean endpointPixels=true,interpolation=true;int oldDark=0,newMinusTwo=0;for(float level:new float[]{-3,-2,0,2,3}){ExposureScale.Plan plan=ExposureScale.plan(level,scaleLimits);Bitmap hardwareImage=Bitmap.createBitmap(1,1,Bitmap.Config.ARGB_8888);int v=Math.round(32*FilmStrength.exposure(plan.hardware));hardwareImage.setPixels(new int[]{0xff000000|v<<16|v<<8|v},0,1,0,0,1,1);Film.Settings f=new Film.Settings();f.stock=0;f.grain=f.fade=f.strength=0;f.exposure=ExposureMatch.withFine(neutralMatch,plan.fine).amount;Bitmap finalImage=Film.develop(hardwareImage,f);int out=pixel(finalImage);interpolation&=Math.abs(out-Math.round(32*FilmStrength.exposure(plan.target)))<=1;if(level==-3){oldDark=out;endpointPixels&=out==8;}if(level==-2)newMinusTwo=out;if(level==3)endpointPixels&=out==128;hardwareImage.recycle();finalImage.recycle();}check(endpointPixels&&newMinusTwo>oldDark,"Rendered +/-3 endpoints match the old darkest/brightest pixels while new -2 preserves more shadow brightness");check(interpolation,"Simulated native AE plus saved fine correction follows the same continuous exposure target without a second full adjustment");
